import{_ as a,o as e,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const r="/cns_master_docs/teaching-v0.4.0-alpha/07-iq.svg",I=JSON.parse('{"title":"07 用两个坐标表示信号：I/Q 与圆周上的点","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/learn/07-iq/index.md","filePath":"v0.4.0-alpha/learn/07-iq/index.md"}'),i={name:"v0.4.0-alpha/learn/07-iq/index.md"};function s(l,t,n,c,h,p){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="_07-用两个坐标表示信号-i-q-与圆周上的点" tabindex="-1">07 用两个坐标表示信号：I/Q 与圆周上的点 <a class="header-anchor" href="#_07-用两个坐标表示信号-i-q-与圆周上的点" aria-label="Permalink to &quot;07 用两个坐标表示信号：I/Q 与圆周上的点&quot;">​</a></h1><p>接收设备处理无线信号时，常用一对同时刻的数保留幅度和相位信息。为什么不只用一条上下起伏的曲线？先在纸上画一对坐标轴：一个点的位置需要“横着多少”和“竖着多少”两个数。本课从这幅图理解 I/Q，不要求先学复数运算。</p><p>适用 CNS Master <strong>v0.4.0-alpha</strong>。先完成<a href="./../02-wave-quantities/">02 幅度、频率与相位</a>以及<a href="./../04-signal-views/">04 不同观察方式</a>。</p><p><a href="../../../downloads/teaching-v0.4.0-alpha/07-iq.cnsproj" download>下载本课工程：07-iq.cnsproj</a></p><h2 id="学习目标与必要知识" tabindex="-1">学习目标与必要知识 <a class="header-anchor" href="#学习目标与必要知识" aria-label="Permalink to &quot;学习目标与必要知识&quot;">​</a></h2><ul><li>把一个复数样本读成同一时刻的坐标对 <code>(I, Q)</code>。</li><li>区分 I/Q 时域、星座与频谱三个视角。</li><li>通过正、负频率对照，理解只看 I 可能丢掉什么。</li></ul><p><strong>I</strong> 是横坐标，也叫实部；<strong>Q</strong> 是纵坐标，也叫虚部。<code>I+jQ</code> 是把这一对数写在一起的记号，<code>j</code> 满足 <code>j²=-1</code>。本课不需要展开复数乘除。</p><p>点到原点的距离表示幅度，例如 <code>(1,0)</code>、<code>(0,1)</code>、<code>(-1,0)</code> 距离都为 1。点的方向表示相位：一整圈是 <code>2π rad</code>，约 6.283 rad；四分之一圈是 <code>π/2 rad</code>，约 1.571 rad。I 和 Q 各自有正负号，都不能单独当作“幅度大小”。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>复数信号源 1.out ──→ I/Q 分解器 1.in</span></span>
<span class="line"><span>        │                   ├─ i：横坐标 I</span></span>
<span class="line"><span>        │                   └─ q：纵坐标 Q</span></span>
<span class="line"><span>        └── 同一个复数样本可直接用 I/Q 时域或星座观察</span></span></code></pre></div><table tabindex="0"><thead><tr><th>位置</th><th>本课值</th><th>为什么选它</th></tr></thead><tbody><tr><td>复数信号源 1</td><td>cosine；频率 +64 Hz；幅度 1；初相 0；实、虚偏置均为 0</td><td>产生 <code>I=cos(φ)、Q=sin(φ)</code> 的单位圆周信号</td></tr><tr><td>采样率</td><td>1024 Hz</td><td>每转一圈有 1024÷64＝16 个样本，便于认识离散位置</td></tr><tr><td>I/Q 分解器 1</td><td>向量长度 1</td><td>每个 item 就是一对 I、Q，分解后仍是每秒 1024 对相应样本</td></tr></tbody></table><p>这里每个采样时刻只产生<strong>一个复数样本</strong>，其中 I、Q 同时存在。分解器不会另生成一条“延迟后的 Q”，也不把采样率翻倍。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>下载工程。停止其他本地任务后，Ctrl+O 打开文件，选中复数信号源核对上表。先画出 <code>(1,0)</code>、<code>(0,1)</code>、<code>(-1,0)</code>、<code>(0,-1)</code> 四个位置。</li><li>按 F5。工程已保存复数 I/Q、星座及分解后两路的观察器。参数页中，I/Q 和星座观察器均只捕获“复数信号源 1 → 输出”。</li><li>在第一个观察器的“输出”页选“I/Q 时域”。把显示范围缩到约 <strong>0.03125 s</strong>，能看到约两圈对应的两组周期曲线。图例中两条曲线是同一复数样本的两个分量。</li><li>在星座观察器选择“星座”，查看横轴 I、纵轴 Q。使用等比例坐标，或“自动刻度”恢复合适范围；横纵缩放不等会把圆看成椭圆。</li><li>对照分解器的两个实数输出：在其观察器参数页确认捕获为“I/Q 分解器 1 → I”和“→ Q”，输出页用“曲线叠加”。它们应与复数 I/Q 显示中的两个分量分别对应。</li><li>想自己绑定时，从“编辑 → 插入 → 观察器”新建。在参数页输入节点名，点选普通复数输出的候选；<strong>只留这一条捕获</strong>，才能选择 I/Q 时域或星座。不要把复数源和分解器两路塞进同一个观察器。</li><li>可另开单路观察器，绑定“复数信号源 1 → 频谱”，在频率横轴寻找 +64 Hz。完成后 Shift+F5 停止，保留本轮数据查看。</li></ol><h2 id="图像为什么这样" tabindex="-1">图像为什么这样 <a class="header-anchor" href="#图像为什么这样" aria-label="Permalink to &quot;图像为什么这样&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.4.0-alpha/07-iq.svg"><img src="`+r+'" alt="左为 I/Q 随时间变化，右为同一复数样本的 16 个圆周位置"></a></p><p>右图的横纵轴采用相同比例，每个点由同一时刻的 I、Q 组成。数一数圆周上的位置，再回到左图找到对应时刻的 I、Q 值。</p><p>I、Q 时域都按 64 Hz 周期变化，但峰谷出现位置不同。星座图把“同一时刻的 I 和 Q”作为一个点，不再以时间作为横轴。本例应看到半径约 1 的圆周上的 <strong>16 个离散位置</strong>；点很多时仍可能重叠在这些位置。它们不是连续画出的模拟轨迹。</p><p>这幅圆周散点图使用了“星座”显示方式，但信号源此时没有发送四种离散数据，所以不能把它叫作 QPSK 数据星座。下一节中的离散码元映射才规定“哪个点代表哪个编号”。</p><p>复数频谱可以区分旋转的方向：本例主峰在 +64 Hz。这里的正负频率是相位随时间转动方向的表示；不是说真的存在一个“负的无线电发射频率”。</p><h2 id="单参数对照-64-hz-改为-−64-hz" tabindex="-1">单参数对照：+64 Hz 改为 −64 Hz <a class="header-anchor" href="#单参数对照-64-hz-改为-−64-hz" aria-label="Permalink to &quot;单参数对照：+64 Hz 改为 −64 Hz&quot;">​</a></h2><ol><li>停止，只改复数信号源的“频率”为 <strong>−64 Hz</strong>，其他值保持不变，按 F5 重新运行。</li><li>对比同一采样位置的 I、Q：I 的余弦值相同，Q 的正负方向反过来；复数频谱的峰应移至 −64 Hz。</li><li>查看星座散点位置。它仍是同样的圆周位置集合；<strong>一张没有时间顺序的静态散点图不能单独告诉你转动方向</strong>。应结合 I/Q 时域或频谱判断。</li><li>恢复 +64 Hz，再运行一次。</li></ol><p>请解释：如果只留下 I 那条曲线，为什么这两个实验条件难以区分？答案应同时提到本例的初相条件和 Q 中保留的方向信息。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>I/Q 或星座选项不可选</td><td>必须恰好捕获一路普通复数输出，不能是频谱、实数，或混入其他捕获</td></tr><tr><td>看到椭圆</td><td>先核对横纵轴比例，再核对幅度和实、虚偏置；不要立即当作信道失真</td></tr><tr><td>星座不是四个点</td><td>本例是旋转单音，16 点一圈；它没有执行四点码元映射</td></tr><tr><td>星座不显示转动动画</td><td>散点位置可能重复，且显示不保留箭头；用 I/Q 时间变化或正负频谱判断</td></tr><tr><td>Q 被当成幅度而出现负值</td><td>Q 是有符号坐标；真正的幅度是点到原点的距离</td></tr></tbody></table><p>本例没有无线电本振、天线、传播信道或硬件采样。它建立的是复数表示的数学直觉。接下来先用<a href="./../08-fm/">调频与正交解调</a>认识一种“把值放进信号、再取出来”的方法。</p><p>模块参考：<a href="./../../modules/complex_signal_source/">复数信号源</a> · <a href="./../../modules/iq_split/">I/Q 分解器</a> · <a href="./../">返回学习路径</a></p>',27)])])}const g=a(i,[["render",s]]);export{I as __pageData,g as default};
